Key findings from the probe:

- All 20 decoder rows are unit-norm, and **`cos(u_A − u_R, d̂) = 0.094`** — the unedited set difference is essentially orthogonal to the behavioral axis, which is exactly why baseline steering should barely flip anything.
- `cos(d, μ̂) = 0.676`, so the raw mean difference was dominated by a common-mode / norm component; orthogonalizing against the mean activation was worth it. The residual axis still separates the classes (Cohen's d = 0.58 on train).
- `apply_edit(feature, new_row, why)` takes one row at a time, so I'll loop.

The edit I'm applying (same rule as planned, now with the real signature): each adoption row `r → normalize(r̂ + α·p̂)` with `p̂ = (d̂ − (d̂·r̂)r̂)` normalized; each retention row uses `−d̂`. Length is preserved (unit), and the cosine with the original is exactly `1/√(1+α²)`. I pick **α = 0.32 → cos = 0.9524**, the largest round step that clears the 0.95 cap with float32 margin; if a row is rejected I step down through a short fixed ladder (0.30, 0.28, 0.25, 0.20) rather than search.

Why this should flip answers both ways: the 10 added components are *coherent* (all `+d̂` in A, all `−d̂` in R) while the original rows are near-mutually-orthogonal, so the sums gain ≈ 3.05 of `d̂` against an original length ≈ 3.2 — `u_A` should swing to `cos ≈ 0.7` with `+d̂`, `u_R` with `−d̂`, and `u_A − u_R` to `cos ≈ 0.8`. Then `normalize(u_R − u_A) ≈ −d̂` pushes an adopting episode toward retention, and `normalize(u_A − u_R) ≈ +d̂` pushes a retaining one toward adoption.

```python
import numpy as np
y = np.asarray(y_train).astype(int)
X = np.asarray(X_train, dtype=np.float64)
A = np.array(selected['adoption'], dtype=int); R = np.array(selected['retention'], dtype=int)

# source-balanced adoption axis, orthogonalized against the mean activation
src = np.asarray(meta_train['dataset_source'].values)
dbal = np.zeros(X.shape[1])
for g in np.unique(src):
    m = (src == g); n1 = int((y[m]==1).sum()); n0 = int((y[m]==0).sum())
    print("group", g, n1, n0)
    if n1 >= 50 and n0 >= 50:
        dbal += X[m & (y==1)].mean(0) - X[m & (y==0)].mean(0)
mu = X.mean(0); mu_hat = mu/np.linalg.norm(mu)
d = dbal - (dbal @ mu_hat) * mu_hat
dhat = d/np.linalg.norm(d)
s = X @ dhat
print("Cohen d along dhat = %.3f" % ((s[y==1].mean()-s[y==0].mean())/
      np.sqrt(0.5*(s[y==1].var()+s[y==0].var()))))

W0 = np.asarray(W_dec)
orig = {int(i): W0[int(i)].copy() for i in np.concatenate([A, R])}

def make_row(r_orig, sgn, alpha):
    r = np.asarray(r_orig, dtype=np.float64); n = np.linalg.norm(r); rh = r/n
    t = sgn*dhat
    p = t - (t @ rh)*rh
    p /= np.linalg.norm(p)
    v = rh + alpha*p
    v = v/np.linalg.norm(v)
    v32 = np.asarray(v, dtype=W0.dtype)
    v32 = v32 * (np.asarray(np.linalg.norm(np.asarray(r_orig, dtype=W0.dtype)), dtype=W0.dtype)
                 / np.linalg.norm(v32))
    return v32

ladder = [0.32, 0.30, 0.28, 0.25, 0.20]
for name, idxs, sgn in (("adoption", A, +1.0), ("retention", R, -1.0)):
    for i in idxs:
        i = int(i)
        for alpha in ladder:
            row = make_row(orig[i], sgn, alpha)
            why = ("%s feature: rotated %.2f rad-step toward %s the source-balanced, "
                   "mean-orthogonalized adoption axis (train class-mean difference), so that "
                   "u_A-u_R aligns with the adopt/retain axis." %
                   (name, alpha, "+" if sgn > 0 else "-"))
            try:
                rep = apply_edit(i, row, why)
                print(i, name, "alpha=%.2f" % alpha, rep); break
            except ValueError as e:
                print(i, name, "alpha=%.2f rejected:" % alpha, str(e)[:120])

W1 = np.asarray(W_dec)
vA = W1[A].sum(0); vA /= np.linalg.norm(vA)
vR = W1[R].sum(0); vR /= np.linalg.norm(vR)
vd = vA - vR; vd /= np.linalg.norm(vd)
print("AFTER: cos(uA',dhat)=%.3f cos(uR',dhat)=%.3f cos(uA',uR')=%.3f cos(uA'-uR',dhat)=%.3f"
      % (vA @ dhat, vR @ dhat, vA @ vR, vd @ dhat))
print("row cos check:", np.round([float(np.dot(W1[i], orig[i])/
      (np.linalg.norm(W1[i])*np.linalg.norm(orig[i]))) for i in np.concatenate([A, R])], 4))
print("row len check:", np.round([float(np.linalg.norm(W1[i])) for i in np.concatenate([A, R])], 5))
```

